choose.otherwise:
select mt.id, mt.tech_code as code, mt.tech_name as name, mt.tech_format as format, mt.tech_price as price, mt.price_type as category, d.dept_name as department from medical_technology mt join department d on d.id = mt.deptment_id where mt.tech_type = #{type}
and (mt.tech_name like concat('%', #{keyword}, '%') or mt.tech_code like concat('%', #{keyword}, '%'))
order by mt.tech_code

mapper.insert:
insert into prescription(register_id, drug_id, drug_usage, drug_number, created_by,
  unit_price, request_key, request_hash, line_no)
select #{registrationId}, d.id, #{usage}, #{quantity}, #{employeeId}, d.drug_price,
       #{requestKey}, #{requestHash}, #{lineNo}
from drug_info d where d.id = #{drugId}
